events = []
class Sep(str):
    def __len__(self):
        events.append('len')
        return 1
    def __str__(self):
        raise AssertionError('str conversion')
class Group:
    def __index__(self):
        events.append('index')
        return -1
for fn in (hexlify, b2a_hex):
    for sep, expected in ((Sep(''), b'41\x0042'), (Sep('ab'), b'41a42'), (Sep('é'), b'41\xe942')):
        events.clear()
        assert fn(b'AB', sep, Group()) == expected
        assert events == ['index', 'len']
    events.clear()
    try:
        fn(b'AB', Sep('aĀ'), Group())
    except ValueError as error:
        assert error.args == ('sep must be ASCII.',)
    else:
        assert False
    assert events == ['index', 'len']

class Text(str):
    def __str__(self):
        raise AssertionError('str')
    def __len__(self):
        raise AssertionError('len')
    def __iter__(self):
        raise AssertionError('iter')
class Data(bytes):
    def __bytes__(self):
        raise AssertionError('bytes')
    def __len__(self):
        raise AssertionError('len')
    def __iter__(self):
        raise AssertionError('iter')
for fn in (unhexlify, a2b_hex):
    assert fn(Text('4142')) == b'AB'
    assert fn(Data(b'4142')) == b'AB'
    assert type(fn(Text('4142'))) is bytes
for fn in (hexlify, b2a_hex):
    assert fn(Data(b'AB')) == b'4142'
    assert type(fn(Data(b'AB'))) is bytes

events = []
failure = ValueError('retained')
class Sep(str):
    def __len__(self):
        events.append('len')
        raise failure
class Group:
    def __index__(self):
        events.append('index')
        if broken:
            raise failure
        return 1
for fn in (hexlify, b2a_hex):
    for broken in (False, True):
        events.clear()
        try:
            fn(b'AB', Sep(':'), Group())
        except ValueError as error:
            assert error is failure
        else:
            assert False
        assert events == (['index'] if broken else ['index', 'len'])

